## Why This Is Asked

This question tests expertise with closures, per-id memoization, and real-time rendering patterns in frontend systems. It specifically targets race-condition handling and efficient UI updates under high-frequency data scenarios.

## Key Concepts

- Closure-scoped per-id caches for memory efficiency
- Per-id memoization with bounded history management
- Promise chaining to serialize renders and handle race conditions
- Debounce using requestAnimationFrame for smooth UI updates

## Code Example

```javascript
function createDataUpdater() {
  const cache = new Map(); // id -> [last 5 results]
  let renderPromise = Promise.resolve();
  let renderScheduled = false;

  const updateCache = (id, data) => {
    const history = cache.get(id) || [];
    history.push(data);
    if (history.length > 5) history.shift();
    cache.set(id, history);
  };

  const render = () => {
    renderScheduled = false;
    // Apply cache data to UI
  };

  const scheduleRender = () => {
    if (!renderScheduled) {
      renderScheduled = true;
      requestAnimationFrame(render);
    }
  };

  return {
    processBatch: (batch) => {
      renderPromise = renderPromise.then(() => {
        batch.forEach(item => updateCache(item.id, item.data));
        scheduleRender();
      });
    }
  };
}
```

## Trade-offs

**Pros:**
- Closure ensures encapsulation and prevents external cache mutation
- Bounded cache prevents memory leaks from unbounded growth
- Promise chain guarantees render ordering consistency
- requestAnimationFrame provides optimal browser rendering timing

**Cons:**
- Added complexity compared to simple direct updates
- Memory overhead from maintaining per-id histories
- Potential render lag if batches arrive faster than processing capacity
- Cache management adds computational overhead per item

## Why This Is Asked
Assesses practical ability to manage per-key caching, in-flight request deduplication, and request cancellation using closures and promises in a real-world data-loading module.

## Key Concepts
- Closure-based per-key state management
- In-flight request deduplication and cancellation with AbortController
- TTL-based cache invalidation
- Async/await error handling and race condition management

## Code Example
```javascript
function createLoader() {
  const cache = new Map();
  return async function load(query, page) {
    const key = JSON.stringify({ query, page });
    const now = Date.now();
    const cached = cache.get(key);
    if (cached && now - cached.timestamp < 5 * 60 * 1000) {
      return cached.data;
    }
    if (cached?.controller) {
      cached.controller.abort();
    }
    const controller = new AbortController();
    cache.set(key, { controller, timestamp: now });
    try {
      const response = await fetch(`/api/items?query=${query}&page=${page}`, { signal: controller.signal });
      const data = await response.json();
      cache.set(key, { data, timestamp: now });
      return data;
    } catch (err) {
      if (err.name !== 'AbortError') throw err;
    }
  };
}
```

Closures enable functional patterns: private state, currying, and memoization. Trade-offs: closures keep references alive, increasing memory footprint; avoid capturing huge objects. Edge cases: loops with var can close over the wrong index; use let. In UIs, closures can lead to stale state if components re-render without updating bindings; debouncing/memoization illustrate how closures bind behavior to a specific creation context. Debounce example:
```
const debounce = (fn, wait) => {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), wait);
  };
};
```

## Why This Is Asked
This question tests the ability to design an offline-first, real-time collaboration feature using the Canvas API, WebSocket communication, and Service Workers. It evaluates understanding of robust reconnection strategies, multi-client synchronization, and cross-tab coordination.

## Key Concepts
- Canvas rendering with minimal DOM manipulation; use a single render loop via requestAnimationFrame
- WebSocket-based real-time synchronization with an operation log and CRDT-like merge logic
- Service Worker caching for the app shell and board bitmap to enable offline use
- Cross-tab coordination via BroadcastChannel with resilient reconnect and exponential backoff strategies

## Code Example
```javascript
// WebSocket wrapper (connect, backoff, send, onMessage)
class WS {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.reconnectDelay = 1000;
    this.maxReconnectDelay = 30000;
    this.handlers = {};
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onopen = () => { this.reconnectDelay = 1000; };
    this.ws.onclose = () => this.reconnect();
    this.ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      this.handlers[msg.type]?.(msg.payload);
    };
  }

  reconnect() {
    setTimeout(() => {
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.connect();
    }, this.reconnectDelay);
  }

  send(type, payload) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    }
  }

  on(type, handler) {
    this.handlers[type] = handler;
  }
}

// opLog for CRDT-like merge
class OpLog {
  constructor() {
    this.ops = [];
    this.vectorClock = {};
  }

  addOp(op) {
    this.ops.push(op);
    this.vectorClock[op.clientId] = (this.vectorClock[op.clientId] || 0) + 1;
  }

  merge(remoteOps) {
    for (const op of remoteOps) {
      const dominated = this.ops.some(local =>
        local.clientId === op.clientId && local.timestamp <= op.timestamp
      );
      if (!dominated) {
        this.ops.push(op);
      }
    }
  }
}

// Service Worker (install/activate/cache)
// sw.js
self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open('whiteboard-v1').then(cache => cache.addAll(['/', '/index.html', '/app.js']))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== 'whiteboard-v1').map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request))
  );
});

// Main render wiring
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const ws = new WS('ws://localhost:8080');
const opLog = new OpLog();

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const op of opLog.ops) {
    ctx.beginPath();
    ctx.moveTo(op.x1, op.y1);
    ctx.lineTo(op.x2, op.y2);
    ctx.stroke();
  }
  requestAnimationFrame(render);
}

canvas.addEventListener('mousemove', (e) => {
  if (e.buttons !== 1) return;
  const op = { x1: lastX, y1: lastY, x2: e.offsetX, y2: e.offsetY };
  opLog.addOp(op);
  ws.send('stroke', op);
  lastX = e.offsetX;
  lastY = e.offsetY;
});

ws.on('stroke', (op) => opLog.addOp(op));
ws.connect();
render();
```

